/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
import vtk
r=vtk.vtkXMLImageDataReader();r.SetFileName('/workspace/cloud/cloud1.vti');r.Update()
d=r.GetOutput();print('dims',d.GetDimensions(),'bounds',d.GetBounds())
for pd in (d.GetPointData(),d.GetCellData()):
 print('arrays',pd.GetNumberOfArrays())
 for i in range(pd.GetNumberOfArrays()): print(pd.GetArrayName(i),pd.GetArray(i).GetRange())
try:
 from paraview.simple import *
 print('simple ok')
except Exception as e: print(e)
PY
find /opt/conda -iname '*ttk*' | sed -n '1,100p'"

